      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"32\">KNOWLEDGE CHECK</text><rect x=\"130\" y=\"150\" width=\"840\" height=\"250\" rx=\"20\" fill=\"#6366f1\" fill-opacity=\"0.12\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"210\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"21\">INTUITION, RESEARCH-DEFINED</text><text x=\"550\" y=\"255\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"18\">Compressed pattern recognition</text><text x=\"550\" y=\"290\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"18\">Built from accumulated experience</text><text x=\"550\" y=\"325\" text-anchor=\"middle\" fill=\"#888\" font-size=\"16\">Faster than conscious analysis, not magic</text><circle cx=\"360\" cy=\"540\" r=\"75\" fill=\"#0ea5e9\" fill-opacity=\"0.18\" stroke=\"#0ea5e9\" stroke-width=\"2\"/><text x=\"360\" y=\"535\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"15\">1000s OF</text><text x=\"360\" y=\"558\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"13\">PRIOR CASES</text><path d=\"M440 540 L530 540\" stroke=\"#ffd700\" stroke-width=\"3\"/><polygon points=\"530,540 515,528 515,552\" fill=\"#ffd700\"/><circle cx=\"740\" cy=\"540\" r=\"75\" fill=\"#ffd700\" fill-opacity=\"0.15\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"740\" y=\"535\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"15\">ONE FAST</text><text x=\"740\" y=\"558\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"13\">GUT CALL</text></svg>",
